Definition rf2_at (L S Zr : list (word * word)) (mo : Model)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (lo c CA P R sb ARI rbeg FAB TH TSD CTX nf mfa au mu : Z) (fl : list Z) (msF' : machine_state) (mo' : Model) : Prop :=
  exists (t0 t1 t2 a5 a6 a7 x7 x8 x9 s10' s11' t3 t4 t5 t6 q0 q1 q2 q3 : word) (j8 j24 : list byte) m',
  let n := rf_n c in let total := rf_total c nf au in
     lzok bsegs L S Zr (mkCfg msF' mo')
  /\ restrict L S msF'
     = MS (mkR (wz 0x55320) (Z_to_bv 64 (bv_unsigned sp + -224)) gp tp t0 t1 t2 (wz R) (wz (CA + 2560)) (wz AINST) (wz (Z.shiftl c 32)) (wz c) (wz au) (wz (n - nf)) a5 a6 a7
               (wz rbeg) (wz total) (wz mu) (wz (class_size c)) (wz n) x7 x8 x9 s10' s11' t3 t4 t5 t6)
          F (Z_to_bv 64 (if mu <? total then 0x5540c else 0x554e0)) fc None m' (seg_rom bsegs)
  /\ same_but_materialized mo mo'
  /\ munch ((lo, bv_unsigned sp) :: (R, R + 8) :: icW CA) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
  /\ RENV tp TSD CTX TH sb ARI m'
  /\ stk bsegs m' lo (bv_unsigned sp + -224)
  /\ rw_cells bsegs m' (bv_unsigned sp + -224)
       [C8 (wz n); C8 (wz (P + 16)); C8 (wz FAB); C8 (wz (2^61)); C8 (wz (R + 8)); C8 (wz AINST); C8 (wz R); C8 (wz 0x55320)]
  /\ rw_cells bsegs m' (bv_unsigned sp + -160)
       [CB 24 j24; C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 (wz n); C8 (wz P); C8 (wz 0x54fa4)]
  /\ rw_cells bsegs m' (bv_unsigned sp + -32) [CB 8 j8; C8 s1; C8 s0; C8 ra]
  /\ rw_cells bsegs m' P [C4 (wz 0)] /\ stk bsegs m' (P + 16) (P + 80)
  /\ (forall c', 1 <= c' <= 31 -> rw_cells bsegs m' (CA + 80 * c' + 4) [C4 (wz (max_count c'))] /\ rw_cells bsegs m' (CA + 80 * c' + 8) [C8 (wz (class_size c'))])
  /\ rw_cells bsegs m' (TH + 2768) [C8 q0; C8 q1; C8 q2; C8 q3] /\ stk bsegs m' (TH + 2800) (TH + 3168)
  /\ rw_cells bsegs m' R (rinfo_cells nf mfa au mu)
  /\ stk bsegs m' (R + 64) (R + 68) /\ rw_cells bsegs m' (R + 68) [C1 (b8 0)] /\ stk bsegs m' (R + 69) (R + 128)
  /\ u32arr bsegs m' FAB (wlist (rev fl)) /\ stk bsegs m' (FAB + 4 * nf) (FAB + mfa) /\ stk bsegs m' (rbeg + au) (rbeg + mu).

