  Lemma rf_nomap : forall msF1 mo1, nf < n -> rf_total c nf au <= mu ->
    rf2_at L S Zr mo ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo c CA P R sb ARI rbeg FAB TH TSD CTX nf mfa au mu fl msF1 mo1 ->
    (forall msF' mo', rf3_at L S Zr mo ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo c CA P R sb ARI rbeg FAB TH TSD CTX nf mfa au mu mu fl msF' mo' ->
                      sreach bsegs Q (mkCfg msF' mo')) ->
